import type { ToolDefinition } from "@/lib/tools/registry";

export type ToolFaq = { question: string; answer: string };
type FaqSet = readonly [ToolFaq, ToolFaq, ToolFaq, ToolFaq];

const faq = (question: string, answer: string): ToolFaq => ({ question, answer });

// Keys use the category and slug so tools with the same slug remain distinct.
const faqSets: Record<string, FaqSet> = {
  "converters/px-rem": [faq("How do I convert px to rem?", "Enter a pixel value and the root font size; the default root size is 16 px. The result is the pixel value divided by that root size."), faq("How do I convert rem to px?", "Enter the rem value and root font size. The tool multiplies them to calculate pixels."), faq("Why change the root font size?", "CSS rem units are relative to the document root font size. Use the value configured by your project, since it may differ from 16 px."), faq("Does this change my CSS?", "No. It calculates values for you to copy into your stylesheet; it does not edit or inspect a project.")],
  "converters/rem-em": [faq("What is the difference between rem and em?", "Rem is relative to the root element's font size. Em is relative to the current element's inherited or set font size."), faq("How do I convert rem to em?", "Enter the rem value, root font size, and parent font size. The conversion compares the resulting pixel sizes."), faq("Why do I need a parent font size?", "An em value depends on its context. The parent font size provides the reference needed for a meaningful comparison."), faq("Will this update my stylesheet?", "No. The result is a calculation to use in your CSS; it does not modify project files.")],
  "converters/bytes": [faq("What is the difference between MB and MiB?", "MB uses decimal units (1 MB = 1,000,000 bytes); MiB uses binary units (1 MiB = 1,048,576 bytes). The tool labels these systems separately."), faq("Which storage units can I convert?", "Convert bytes through decimal kB, MB, GB, TB and binary KiB, MiB, GiB, TiB."), faq("Why do file sizes differ between apps?", "Some systems report decimal units and others binary units, and displayed values may also be rounded."), faq("Is my value stored?", "No. The conversion runs in your browser and the input is not uploaded or saved.")],
  "converters/milliseconds": [faq("What values can I convert?", "Enter a duration in milliseconds, including a fractional value, to see equivalent units through days."), faq("Can I convert a duration back to milliseconds?", "Yes. Choose the input unit and enter its value; the tool calculates the equivalent duration."), faq("Are these calendar days?", "No. A day here is a fixed 24-hour duration, not a date affected by a calendar or timezone."), faq("How precise are the results?", "Results are numeric duration conversions and may be rounded for display; they are not tied to a particular clock or date.")],
  "converters/unit-converter": [faq("Which measurement types are supported?", "The converter handles common length, mass, and temperature units. Select the quantity and units shown in the controls."), faq("How does temperature conversion work?", "Temperature uses the correct offset and scale formulas for Celsius, Fahrenheit, and Kelvin; it is not a simple ratio."), faq("Why can’t I convert length to mass?", "Those are different physical quantities. Select units from the same measurement type to get a valid conversion."), faq("Are results approximate?", "The conversion uses standard unit relationships and displays a rounded result. It is a general-purpose converter, not a measurement instrument.")],
  "converters/unix-timestamp": [faq("What is a Unix timestamp?", "It is the elapsed time since 1970-01-01 00:00:00 UTC, commonly represented in seconds or milliseconds."), faq("How do I know whether a timestamp is seconds or milliseconds?", "Seconds are typically ten digits and milliseconds thirteen, though digit count is only a clue. Select the correct unit in the tool."), faq("Why do local and UTC dates differ?", "UTC is the shared reference time. Your local display uses the browser's timezone and may show a different calendar date."), faq("Can I enter an ISO date?", "Yes. Use the date input to convert a date and time to Unix seconds and milliseconds, with UTC and local time shown.")],
  "converters/timezone-converter": [faq("How do I convert a time between timezones?", "Choose the source date, time, and IANA timezone, then select the destination timezone to view the corresponding local time."), faq("What is an IANA timezone?", "It is a named timezone such as Asia/Kolkata or America/New_York. Names carry regional daylight-saving rules, unlike fixed UTC offsets."), faq("Why can the offset change during the year?", "Some regions change their clocks seasonally. The converter applies the timezone rules for the selected date."), faq("Does it account for daylight saving time?", "It uses the browser's timezone database for the selected IANA zones. Ambiguous or nonexistent local times around clock changes can still require judgment.")],
  "converters/date-difference": [faq("How is the date difference calculated?", "The tool reports elapsed days and a calendar-based years, months, and days breakdown between the selected dates."), faq("Is the number of days inclusive?", "Elapsed days count the interval between the dates; they do not count both endpoints as full days."), faq("Why does the calendar breakdown differ from dividing days by 30?", "Calendar months have different lengths, so the years-months-days result follows calendar boundaries rather than a fixed month length."), faq("Does time of day affect the result?", "This tool compares calendar dates. It is not a precise elapsed-hours calculator.")],
  "converters/json-query-string": [faq("What JSON can this converter handle?", "It converts flat JSON objects and query strings. Nested objects and arrays are outside the supported flat mapping."), faq("Are repeated query parameters preserved?", "Yes. Repeated keys in a query string are retained when converting between the supported representations."), faq("Should I include the question mark?", "You may paste a URL query string with or without its leading question mark; use the query-string input field."), faq("Why are some characters encoded?", "Query strings percent-encode characters that have special meaning in URLs. Decode the result when you need readable text.")],
  "converters/cron-generator": [faq("What cron format does this generate?", "It generates common five-field cron expressions for minute, hour, day of month, month, and day of week."), faq("How do I schedule something every day?", "Set the hour and minute you want and leave the other schedule fields at their default wildcard values."), faq("Does the expression include a timezone?", "No. Cron timezone behavior depends on the scheduler that runs it; check that system's timezone configuration."), faq("Will this run my scheduled task?", "No. It builds an expression for you to copy into a compatible scheduler.")],
  "converters/cron-explainer": [faq("Which cron syntax is supported?", "The explainer validates common five-field cron syntax, including lists, ranges, and steps."), faq("What do the five fields mean?", "They represent minute, hour, day of month, month, and day of week, in that order."), faq("Does it explain special cron extensions?", "No. This tool focuses on the common five-field format; scheduler-specific extensions may not be recognized."), faq("Does the explanation confirm the job will run?", "It explains the expression syntax. Actual execution also depends on the scheduler, timezone, and job configuration.")],
  "converters/css-units": [faq("Which CSS units can I convert?", "The converter handles CSS lengths including px, rem, em, viewport units, and physical units, with explicit assumptions for context-dependent values."), faq("Why do rem and em conversions need font sizes?", "Rem depends on the root font size and em on the relevant element or parent size. Enter the values used by your design."), faq("How are vw and vh calculated?", "Viewport units depend on viewport dimensions. Provide the viewport width or height used for the calculation."), faq("Will this match every browser layout?", "It is a mathematical conversion using your supplied assumptions; actual rendered layout can also depend on CSS and browser behavior.")],
  "converters/currency": [faq("Where do exchange rates come from?", "The tool requests an indicative reference rate from Frankfurter when you refresh or convert. It does not send your amount."), faq("Are the rates real-time?", "They are reference rates with a published date, not live trading quotes. Check the displayed date before relying on a result."), faq("Are fees or bank rates included?", "No. The estimate excludes provider spreads, fees, taxes, and card or bank exchange rules."), faq("Why does conversion need an internet connection?", "The selected currency pair's public rate is fetched on demand. Your amount and other inputs stay in your browser.")],
  "markdown/editor": [faq("Which Markdown syntax is supported?", "The editor previews common Markdown and GitHub Flavored Markdown features, including tables and task lists."), faq("Does the preview render raw HTML?", "No. Raw HTML is not rendered. Links are limited to safe schemes, and remote images are blocked; relative image paths can be shown."), faq("Is my draft saved automatically?", "No. The editor works locally in the current page and does not upload or save your source."), faq("Why does a preview look different from another Markdown site?", "Markdown implementations and site-specific styling vary. This preview is intended as a useful local approximation.")],
  "markdown/to-html": [faq("How do I convert Markdown to HTML?", "Paste or type Markdown in the input and generate the HTML document, then copy or download the result."), faq("Is raw HTML from my Markdown included?", "Raw HTML is ignored. The output is sanitized and limited to the tool's supported safe HTML policy."), faq("Which Markdown features work?", "The converter supports the shared CommonMark and GitHub Flavored Markdown syntax used by the app, including tables and task lists."), faq("Can the exported HTML load external content?", "Links are limited to http, https, mailto, and tel; images must use relative paths. Scripts, event handlers, embedded content, and user CSS are removed.")],
  "markdown/to-markdown": [faq("How do I convert HTML to Markdown?", "Paste HTML into the input, review the generated Markdown, and copy or download it."), faq("Does the tool display or run the pasted HTML?", "No. It parses and converts the markup locally without rendering it as a webpage or executing scripts."), faq("Will the result preserve every style?", "Markdown cannot represent all HTML styling or layout. The conversion keeps supported structure and may simplify unsupported elements."), faq("Can I convert a full webpage URL?", "The input is pasted HTML. Fetch or copy the page source yourself before converting it.")],
  "markdown/to-pdf": [faq("What Markdown features appear in the PDF?", "Headings, paragraphs, emphasis, lists, task markers, blockquotes, code, rules, tables, and safe links are laid out in the PDF."), faq("Can the PDF include images?", "Images are not fetched; their alt text is used in place of image content. Raw HTML blocks appear as literal text."), faq("Can I change the page layout?", "Choose A4 or US Letter, portrait or landscape, margins, a standard font, body size, title metadata, and page numbers."), faq("Why might some characters fail to export?", "Built-in PDF fonts support basic Latin and many Windows-1252 characters. Unsupported characters are reported; input and output have size and page limits.")],
  "markdown/to-docx": [faq("What Markdown content is converted?", "The converter creates a formatted Word document from the supported Markdown and GitHub Flavored Markdown structures."), faq("Can I edit the generated DOCX?", "Yes. Download the file and open it in a compatible word processor for further editing."), faq("Will the DOCX exactly match the preview?", "No. Markdown structure is carried into a Word document, but fonts, page layout, and rendering vary between word processors."), faq("Is my Markdown uploaded?", "No. Parsing and DOCX generation run locally in your browser; the content is not uploaded or saved.")],
  "markdown/table-generator": [faq("How do I add or remove table cells?", "Use the table controls to set up rows and columns, then enter text in each cell."), faq("How are special characters handled?", "The generated Markdown escapes characters that could otherwise break table cells, including vertical bars."), faq("Can I choose column alignment?", "Set each column's alignment in the controls; the exported Markdown uses the matching separator markers."), faq("Where can I use the result?", "Copy or download the Markdown table for a Markdown document or editor that supports table syntax.")],
  "markdown/table-to-markdown": [faq("What table input can I convert?", "Paste tab-separated or comma-separated data, or an HTML table. The tool parses it locally into Markdown."), faq("How should I format CSV input?", "Use commas between fields and newlines between rows. Quoted CSV fields can contain commas or line breaks."), faq("What happens to HTML styling?", "The converter keeps table content and structure, not visual styling. Output is a plain Markdown table."), faq("Are Markdown special characters escaped?", "Yes. Cell text is escaped so vertical bars and other table syntax characters do not split cells unexpectedly.")],
  "markdown/toc-generator": [faq("How are headings found?", "The generator reads actual Markdown heading syntax and creates nested links from those headings."), faq("Are duplicate heading names supported?", "Yes. Generated anchor slugs are made duplicate-safe so repeated headings receive distinct links."), faq("Are headings inside code blocks included?", "No. Code examples are not treated as document headings."), faq("Will these links match every Markdown site?", "Anchor naming can vary between renderers. Review the generated slugs against the destination platform if its heading rules differ.")],
  "markdown/formatter": [faq("What does the formatter change?", "It normalizes supported Markdown heading, list, spacing, and GitHub Flavored Markdown table formatting."), faq("Does it rewrite my wording?", "No. The formatter is for Markdown structure and spacing, not prose editing."), faq("Will it preserve raw HTML?", "Raw HTML handling follows the app's Markdown parser and formatter behavior; review the output before using it in another renderer."), faq("Why did the output change my table or list spacing?", "Consistent spacing is part of formatting. The content is normalized to make the Markdown easier to read and maintain.")],
  "images/convert": [faq("Which image formats can I convert?", "Choose a supported input image and an available output format shown in the tool. Browser codec support can vary by format."), faq("Why does my converted image look different?", "Some formats are lossy or handle transparency differently. Compare the preview and choose a format suited to your use."), faq("Are SVG files supported?", "Supported images are processed in-browser; SVG preview is rendered through the browser. Very complex or unsupported files may fail."), faq("Are images uploaded?", "No. Image conversion runs in your browser, and the selected image is not sent to a server.")],
  "images/resize": [faq("How do I resize an image?", "Choose an image, enter the target dimensions, and run the resize operation. The preview reflects the result."), faq("Can I keep the original aspect ratio?", "Use the aspect-ratio control when you want the image proportions preserved while changing its size."), faq("Does resizing improve image quality?", "Upscaling cannot restore missing detail. For a smaller file, use the compression tool or choose an efficient output format."), faq("Is the original file changed?", "No. The tool creates a separate downloadable result in your browser.")],
  "images/compress": [faq("How do I make an image file smaller?", "Select an image, choose the available format and quality settings, then compare the resulting size before downloading."), faq("Why did compression make the file larger?", "Some formats or images are already compact. Re-encoding can add overhead; the tool reports the actual size change."), faq("Does lower quality always mean a smaller file?", "Usually for lossy formats, but the result depends on image content and format. Compare the measured output size."), faq("Is compression lossless?", "Lossless behavior depends on the selected format. Lossy formats can reduce visual detail as quality is lowered.")],
  "images/crop": [faq("How do I crop an image?", "Select an image, choose a preset aspect ratio or custom crop, adjust the preview, then generate and download the crop."), faq("What does aspect ratio mean?", "It is the relationship between crop width and height, such as square or widescreen. It does not specify pixel dimensions by itself."), faq("Can I undo a crop?", "The source image remains available while the tool is open. Adjust the crop again or reset the tool before downloading."), faq("Will the crop reduce image quality?", "Cropping removes pixels outside the selected area. Output quality also depends on the chosen image format.")],
  "images/transform": [faq("Can I rotate an image by any angle?", "Use the rotation controls provided by the tool. The image is rendered into a new output after transformation."), faq("What is the difference between flip horizontal and vertical?", "A horizontal flip mirrors left and right; a vertical flip turns the image top to bottom."), faq("Does rotation change the dimensions?", "Rotating or flipping changes the rendered image orientation. The resulting dimensions depend on the selected transformation and output."), faq("Can I download the transformed image?", "Yes. Run the transformation and download the generated output; the source file is not overwritten.")],
  "images/adjust": [faq("What image settings can I adjust?", "Use the available brightness, contrast, saturation, grayscale, and blur controls to preview changes."), faq("Can I compare the adjustment with the original?", "The selected source stays available in the current tool session. Reset the controls to return to its unadjusted appearance."), faq("Are adjustments reversible?", "The source is not overwritten. Adjust the controls again or reset before generating a new downloadable version."), faq("Will adjustments preserve the original format?", "Choose from the output options provided. Re-encoding can affect quality and transparency.")],
  "images/base64": [faq("What is a Data URL?", "A Data URL includes a media type and Base64 data, so it can represent an image inline. Raw Base64 contains only the encoded data."), faq("How do I encode an image?", "Select an image and choose whether you need a complete Data URL or the raw Base64 string, then copy the result."), faq("When should I use raw Base64 instead?", "Use raw Base64 when an API or code field expects only encoded bytes. Use a Data URL when the media type prefix is required."), faq("Is the image uploaded?", "No. Encoding happens in your browser. Large encoded strings can be much bigger than the original image.")],
  "images/base64-to-image": [faq("What should I paste into the input?", "Paste raw image Base64 or a complete image Data URL, using a supported image encoding."), faq("Why is my Base64 value rejected?", "It may be truncated, malformed, or encode data that is not a supported image. Check that you copied the complete value."), faq("Can I preview and download the decoded image?", "Yes. A valid value is decoded locally and shown as an image that you can download."), faq("Is the Base64 sent to a server?", "No. Decoding and preview happen in your browser.")],
  "images/exif": [faq("What metadata can the viewer show?", "It reads supported image metadata, which may include camera details and location fields when present in the file."), faq("Why are some EXIF fields missing?", "Metadata can be absent, stripped, or stored in a format the browser tool does not support. Missing values do not prove a field was never recorded."), faq("Does viewing metadata change my photo?", "No. The tool inspects the selected file and does not modify it."), faq("Is my image or location data uploaded?", "No. Inspection runs locally in your browser; the file and metadata are not uploaded.")],
  "images/remove-exif": [faq("How does metadata removal work?", "The tool re-encodes the selected image to produce a new file without supported metadata."), faq("Does it remove every possible metadata field?", "Metadata handling depends on the input and output format. Re-encoding removes metadata supported by this process, but inspect the result if complete removal is critical."), faq("Will image quality or transparency change?", "Re-encoding can affect quality or transparency depending on the chosen format. Check the output before sharing it."), faq("Is the photo uploaded?", "No. Re-encoding happens in your browser and creates a separate download.")],
  "images/favicon": [faq("What files does the favicon generator create?", "It creates PNG favicon files at 16, 32, and 48 pixels from your selected image."), faq("What source image should I choose?", "Use a clear square icon with enough resolution for downscaling. Fine details may not remain visible at 16 pixels."), faq("Does it create a favicon HTML tag?", "The generator focuses on PNG files. Add the downloaded icon files and appropriate link tags to your site yourself."), faq("Are generated icons uploaded?", "No. The image is resized locally in your browser.")],
  "images/pwa-icons": [faq("Which PWA icon sizes are generated?", "The generator creates 192 by 192 and 512 by 512 PNG app icons and provides a manifest snippet."), faq("What makes a good source image?", "Choose a square, high-resolution image with the important artwork centered and readable when scaled down."), faq("Does this publish a PWA?", "No. Download the icons and add the snippet to your site's manifest and deployment yourself."), faq("Are my source image and icons uploaded?", "No. Icon generation runs locally in your browser.")],
  "images/thumbnail": [faq("How do I create a thumbnail?", "Select an image, enter the target size, choose fit or crop behavior, and generate the thumbnail."), faq("What is the difference between fit and crop?", "Fit keeps the entire image visible and may leave empty space. Crop fills the requested frame by trimming edges."), faq("Can I use a custom thumbnail size?", "Enter the dimensions needed by your destination. The tool creates a new image at the chosen size."), faq("Will the source be changed?", "No. The thumbnail is a separate downloadable output; the original file remains untouched.")],
  "images/og": [faq("What size is the Open Graph image?", "The generator creates a single 1200 by 630 PNG image, a common social sharing image size."), faq("Can I edit the design in layers later?", "No. This tool exports a flattened image, not a layered design document."), faq("Where do I use the generated image?", "Host the image on your site and reference its public URL in Open Graph metadata for the relevant page."), faq("Is the image generated on a server?", "No. The image is created in your browser and is not uploaded.")],
  "pdf/merge": [faq("How do I choose the order of merged PDFs?", "Add the PDFs in the order you want them to appear. The output follows the displayed file order."), faq("Can I merge password-protected PDFs?", "Encrypted or unsupported PDFs may fail to load. Use a readable, unencrypted copy that you are authorized to process."), faq("Are there file size limits?", "Each PDF and the combined selection are subject to the limits shown by the tool. Very large or malformed documents may fail in the browser."), faq("Are my PDFs uploaded?", "No. Merging happens locally in your browser and produces a new PDF download.")],
  "pdf/inspect": [faq("What can the PDF inspector show?", "It reports file properties, page count, supported document metadata, and page dimensions; it can also extract selectable text."), faq("How do I extract only certain pages?", "Enter page numbers and ranges separated by commas, such as 1-3, 5. The tool checks them against the document."), faq("Why is no text found on a scanned page?", "Scanned pages may contain only images, with no selectable text layer. Use the Image to Text OCR tool on a page image for approximate printed-English recognition."), faq("Does metadata prove who created a PDF?", "No. Metadata may be missing, incomplete, or changed. The inspector reports available fields and does not establish document history.")],
  "pdf/text-to-pdf": [faq("Can I paste formatted text or Markdown?", "This tool lays out plain text. It preserves line breaks and blank lines but does not interpret Markdown or rich-text formatting."), faq("Can I change page and text layout?", "Choose A4 or US Letter, orientation, margins, a standard font, type size, line spacing, and optional repeating headers or footers."), faq("Why are some characters unsupported?", "The built-in PDF fonts support basic Latin and many Windows-1252 characters, but not all scripts or emoji. Unsupported characters are reported."), faq("Is there a document size limit?", "Text input is limited to 1 MiB and output to 500 pages. Generation runs locally and does not upload or save your text.")],
  "pdf/split": [faq("How do I select pages to split?", "Choose the pages or ranges using the page selector, then create a new PDF from the selected pages."), faq("Can I extract multiple page ranges?", "Yes. Enter the page numbers and ranges supported by the selector and review the selection before exporting."), faq("Does splitting reduce PDF file size?", "It creates a PDF with selected pages; it does not optimize or compress their contents."), faq("Are page contents uploaded?", "No. PDF parsing and page extraction run locally in your browser.")],
  "pdf/images-to-pdf": [faq("Which images can I combine into a PDF?", "Select the supported image files shown by the tool. Each image is placed into the generated PDF."), faq("How is image order decided?", "The PDF follows the displayed file order. Arrange the images before creating the document if order matters."), faq("Can I choose paper size or orientation?", "Use the available page settings to control how the images are placed in the PDF."), faq("Will the PDF preserve image quality?", "The output embeds images into PDF pages; final file size and appearance depend on the source images and selected settings.")],
  "pdf/to-png": [faq("How do I convert PDF pages to PNG?", "Select a PDF, choose the pages and render settings, then download each generated PNG page."), faq("Why can rendering take time?", "Each selected page is rendered in your browser. Large pages, high scale, and many pages need more memory and processing."), faq("Can I download all pages in one ZIP?", "The tool provides individual page downloads; ZIP export is not included."), faq("Are there rendering limits?", "The tool applies PDF file and page limits shown in the interface. Use a smaller page selection if your browser runs low on memory.")],
  "pdf/to-jpg": [faq("How do I convert PDF pages to JPG?", "Select a PDF and the pages to render. The tool creates JPG images that can be downloaded individually."), faq("Will transparent page areas stay transparent?", "JPG does not support transparency, so rendered pages use a solid background."), faq("Can I change output quality or size?", "Use the rendering settings available in the tool; higher scale can improve detail while increasing processing time and file size."), faq("Can I download a ZIP of the pages?", "No. Each rendered page is offered as an individual download.")],
  "developer/json": [faq("How do I format JSON?", "Paste JSON and run the formatter to validate and display a readable or minified result."), faq("Why does invalid JSON fail?", "JSON requires quoted property names and strings, valid commas, and supported values. Read the error and correct the reported syntax."), faq("Does the formatter change my data?", "Formatting changes whitespace, not the JSON values. Review the result before using it in an application."), faq("Is my JSON sent anywhere?", "No. Validation and formatting run locally in your browser.")],
  "developer/word-counter": [faq("What does the word counter count?", "It reports words, characters, sentences, paragraphs, and estimated reading time for the text you enter."), faq("Why can word counts differ between apps?", "Apps use different rules for hyphens, punctuation, languages, and whitespace. Treat the count as a consistent estimate."), faq("How is reading time estimated?", "It uses a general reading-speed estimate, so actual time varies with the reader and material."), faq("Is my text saved?", "No. Counting happens locally in your browser and the text is not uploaded or saved.")],
  "developer/json-to-csv": [faq("What JSON shape can be converted to CSV?", "Provide JSON records with consistent, flat fields. Nested values may not map cleanly to spreadsheet columns."), faq("How are commas and quotes handled?", "The generated CSV escapes field contents as needed so commas, quotes, and line breaks do not split values incorrectly."), faq("What if records have different fields?", "Columns are derived from the record data; review the output for missing values or fields that need normalization."), faq("Does conversion upload my data?", "No. Conversion runs locally in your browser.")],
  "developer/csv-to-json": [faq("How should I format CSV input?", "Include a header row and one record per row. Properly quote values that contain commas, quotes, or line breaks."), faq("How are CSV columns named?", "The first row supplies property names for each converted record."), faq("What happens to empty cells?", "They are converted according to the tool's CSV parsing rules. Check the JSON output if empty values matter to your application."), faq("Is my CSV uploaded?", "No. Conversion happens in your browser and the input is not sent to a server.")],
  "developer/json-to-typescript": [faq("What JSON should I provide?", "Paste a representative JSON value or object. The generated TypeScript types reflect the structure and values present in that sample."), faq("Can one sample describe every possible value?", "No. A sample cannot reveal fields or variants that are absent. Include representative cases and review the generated types."), faq("Does the output validate future data?", "It creates TypeScript declarations; runtime data still needs validation if it comes from an untrusted source."), faq("Can I copy the generated types into a project?", "Yes. Review names and optional fields for your codebase before using the generated declarations.")],
  "developer/json-to-yaml": [faq("What JSON can I convert?", "Paste valid JSON and convert it to YAML. Invalid JSON must be corrected before conversion."), faq("Will YAML preserve the same values?", "The converter represents the JSON data in YAML syntax. Review strings and special characters when using the output in a configuration file."), faq("Does it support comments?", "JSON has no comments, so comments are not part of the conversion."), faq("Is the input private?", "Yes. Parsing and conversion happen locally in your browser.")],
  "developer/case-converter": [faq("Which text cases are available?", "Choose a case style from the options shown, such as upper, lower, title, or camel-style casing."), faq("How are acronyms and punctuation handled?", "Case conversion uses simple text rules; unusual capitalization, punctuation, or language-specific words may need manual review."), faq("Does it change line breaks?", "The tool transforms the text according to the selected case option. Review multiline output before copying it."), faq("Is my text uploaded?", "No. The conversion runs locally in your browser.")],
  "developer/remove-duplicate-lines": [faq("How are duplicate lines identified?", "The tool compares lines of your input and keeps one instance of repeated lines according to its current options."), faq("Does line order stay the same?", "The retained lines follow the original text order; only duplicate occurrences are removed."), faq("Are blank lines treated as duplicates?", "Blank-line behavior depends on the selected cleanup options. Review the output before replacing your source."), faq("Can I undo the result?", "Keep your original text or paste it back into the input; the tool does not modify an external file.")],
  "developer/sort-lines": [faq("How are lines sorted?", "The tool sorts the input lines using the selected ordering option. Review case and number ordering if exact collation matters."), faq("Can I sort numbers naturally?", "Text sorting may order numeric strings differently from numeric values. For numeric ordering, normalize the data first."), faq("Are blank lines kept?", "Blank-line treatment follows the available options. Check the result for the layout you need."), faq("Is my input saved?", "No. Sorting happens locally in your browser.")],
  "developer/remove-empty-lines": [faq("What counts as an empty line?", "The tool removes lines that are empty or contain only whitespace, based on its cleanup behavior."), faq("Will it remove indentation from other lines?", "The operation targets empty lines; check the output if whitespace within non-empty lines is important."), faq("Can I preserve paragraph spacing?", "Removing empty lines removes those separators too. Keep a copy or use find-and-replace if you need selective spacing."), faq("Is my text sent to a server?", "No. Cleanup is performed locally in your browser.")],
  "developer/find-replace": [faq("Is find-and-replace case sensitive?", "Use the tool's available options to control matching behavior. Check the preview or result before copying changes."), faq("Does it treat the search as a regular expression?", "This utility is for literal find-and-replace. Use the Regex Tester for pattern-based matching."), faq("Can I replace text across multiple lines?", "Paste the full text and use the controls provided. Newline behavior depends on the entered search and replacement values."), faq("Can I undo a replacement?", "The tool does not change an external document. Keep the original text in the input or paste it back to revise the operation.")],
  "developer/diff": [faq("How do I compare two texts?", "Paste the original and changed versions into their respective fields to view the differences."), faq("What does the diff highlight?", "It identifies changed, added, or removed text according to the tool's comparison behavior."), faq("Why does formatting affect the diff?", "Whitespace and line breaks are part of text, so even layout changes can appear as differences."), faq("Is either text uploaded?", "No. Comparison happens locally in your browser.")],
  "developer/url-encode": [faq("When should I URL-encode text?", "Encode data that will be placed in a URL component so reserved characters do not change the URL structure."), faq("Can I decode a full URL?", "This tool encodes or decodes URL text. Encode individual components when possible; encoding a whole URL can alter its separators."), faq("Why do spaces look different after encoding?", "Percent encoding represents characters as bytes. Different URL contexts can use different conventions for spaces."), faq("Is my text sent anywhere?", "No. Encoding and decoding run locally in your browser.")],
  "developer/html-entities": [faq("What does HTML entity encoding do?", "It replaces selected characters with HTML entity forms so they can be represented safely in HTML text."), faq("Does encoding make HTML safe to insert anywhere?", "No. Safe handling depends on context, such as text, attributes, or scripts. Use context-appropriate escaping and sanitization."), faq("Can I decode entities too?", "Yes. Switch to decode mode and paste the entity-containing text."), faq("Is my input uploaded?", "No. Conversion runs locally in your browser.")],
  "developer/unicode": [faq("What can the Unicode converter show?", "Enter text or a code point using the input format indicated by the tool to inspect or convert Unicode values."), faq("Why do some symbols display as boxes?", "Your browser or font may not have a glyph for the character, even when the underlying Unicode value is valid."), faq("Are code points the same as UTF-8 bytes?", "No. A Unicode code point identifies a character value; UTF-8 encodes that value as one or more bytes."), faq("Does conversion change the original text?", "It shows a converted representation in the browser. Copy the result you need; the source is not uploaded.")],
  "developer/regex": [faq("How do I test a regular expression?", "Enter a pattern and sample text, then review the matches and captures shown by the tool."), faq("Which regex syntax is used?", "The tester uses browser JavaScript regular-expression behavior. Other languages and engines can differ."), faq("Why does my pattern need escaping?", "Characters such as slashes and backslashes have special meaning in patterns or delimiters. Escape them according to the displayed input format."), faq("Is my sample text uploaded?", "No. Matching runs locally in your browser.")],
  "developer/cron-explainer": [faq("Which cron format is supported?", "This tool explains common five-field cron expressions with lists, ranges, and step values."), faq("What order are the fields in?", "Minute, hour, day of month, month, then day of week."), faq("Can it predict exact run dates?", "It explains and validates syntax; it does not simulate executions across a particular scheduler or timezone."), faq("Why does another scheduler reject my expression?", "Schedulers may use different field counts or extensions. Check the target system's cron documentation.")],
  "developer/cron-generator": [faq("How do I create a cron schedule?", "Choose the desired values in the five schedule fields and copy the generated expression."), faq("What does an asterisk mean?", "A wildcard matches every allowed value for that field, subject to the other schedule fields."), faq("Does the schedule include a timezone?", "No. The scheduler determines the timezone and when the expression runs."), faq("Will this install or run the task?", "No. It generates a cron expression for use in your own scheduler.")],
  "developer/gitignore": [faq("How do I generate a .gitignore file?", "Choose the technologies or tools used in your project, then copy or download the generated ignore patterns."), faq("Will these rules cover every file I should ignore?", "The generated patterns are a starting point. Review them for your project and keep secrets out of version control."), faq("Where should I put the file?", "Save the result as `.gitignore` in the repository directory where those patterns should apply."), faq("Does this modify my repository?", "No. It generates text in your browser; you add it to your project yourself.")],
  "web-seo/url-parser": [faq("What can I paste into the URL parser?", "Enter a URL to inspect its protocol, host, path, query, and fragment components."), faq("Why is my URL reported as invalid?", "Check that it includes a valid URL structure. Add a scheme such as https:// when the address is meant to be absolute."), faq("Does parsing visit the website?", "No. Parsing reads the text you enter and does not request the destination page."), faq("Are query values decoded?", "The parser displays URL components according to browser URL parsing. Use the query-string tool to inspect parameters individually.")],
  "web-seo/query-string": [faq("How do I parse query parameters?", "Paste a query string or URL into the tool to inspect its parameter names and values."), faq("Are repeated parameter names supported?", "Yes. Repeated keys are shown as separate values rather than being silently discarded."), faq("Do I include the question mark?", "A leading question mark is accepted as part of a query string; you can also paste a full URL."), faq("Does this send the URL to a server?", "No. Query parsing happens locally in your browser.")],
  "web-seo/user-agent": [faq("What is a user-agent string?", "It is text that a browser or client sends to identify aspects of its software and platform."), faq("How do I find a user-agent string to parse?", "Paste the string you want to inspect, such as one copied from a browser request or developer tools."), faq("Can the parser identify every browser exactly?", "No. User-agent strings can be reduced, spoofed, or changed, so the parsed labels are best-effort clues."), faq("Is my string uploaded?", "No. Parsing runs locally in your browser.")],
  "web-seo/http-status": [faq("How does the HTTP status checker work?", "Enter a URL and request a browser-accessible status check. Cross-origin restrictions can prevent the browser from reading the response."), faq("Why does a CORS error appear?", "The destination server may not allow browser scripts from this site to inspect its response. This does not prove the URL is offline."), faq("Does the result match every visitor's response?", "No. Status can vary by location, authentication, redirects, caching, and request headers."), faq("Is the URL sent to a service?", "The browser makes a request to the URL you check. Avoid entering private or sensitive URLs.")],
  "web-seo/robots-tester": [faq("What should I paste into the robots tester?", "Paste the site's robots.txt content and enter a crawler user-agent and path to test the matching directives."), faq("Does the tester fetch my live robots.txt?", "It checks the content you provide. Paste the current file contents if you want to evaluate a live site's rules."), faq("Does robots.txt block access securely?", "No. It is a crawler request convention, not an access-control system. Protect private content with authentication."), faq("Why might a crawler behave differently?", "Crawlers can interpret directives differently and may use their own documented rules.")],
  "web-seo/sitemap-validator": [faq("What sitemap can I validate?", "Provide sitemap XML in the input. The tool checks the supplied content for parse and structure issues."), faq("Does validation confirm all URLs work?", "No. XML validation does not guarantee pages are reachable, indexable, or accepted by search engines."), faq("Can it validate a sitemap index?", "It checks the sitemap content format supported by the tool. Review nested sitemap behavior against your search platform's requirements."), faq("Is my sitemap fetched automatically?", "The tool validates the content you provide; it does not establish that the submitted file matches the live site.")],
  "web-seo/meta-generator": [faq("What metadata does the generator create?", "It builds title, description, canonical, robots, theme color, language, Open Graph, and X metadata from your fields."), faq("Where do I add the generated tags?", "Add the markup to the relevant page's document head and deploy the change on your website."), faq("Do the character counts guarantee rankings?", "No. Title and description length guidance is approximate; search engines may rewrite snippets and ranking uses many signals."), faq("Does generating tags update my site?", "No. The tool outputs markup for you to copy; it does not access or change your website.")],
  "web-seo/og-preview": [faq("What does the Open Graph preview show?", "It approximates a sharing card from the title, description, page URL, and image URL you enter."), faq("Will social platforms show the exact same card?", "Not always. Platforms may apply their own current rules, caches, image requirements, and metadata support."), faq("Why is my image missing from the preview?", "Check that the image URL is publicly reachable and that the browser can load it. Some sites block cross-origin display."), faq("Does the preview publish metadata?", "No. Copy the generated tags and add them to your page for platforms to read.")],
  "web-seo/x-card-preview": [faq("Which X card types can I preview?", "Choose a summary card or a large-image summary card and enter the corresponding metadata fields."), faq("Is this an exact X preview?", "No. It is an approximation; X can change card rules, cache content, or decline metadata it cannot access."), faq("How do I make the card appear on my website?", "Add the generated X metadata to your page and ensure the page and image are publicly accessible."), faq("Does this post anything to X?", "No. It creates a preview and markup only; nothing is published.")],
  "web-seo/json-ld": [faq("What is JSON-LD used for?", "JSON-LD is structured data embedded in a page to describe entities or content using a vocabulary such as Schema.org."), faq("Does valid JSON-LD guarantee a rich result?", "No. Search engines decide eligibility and display. They can require additional properties or choose not to show a rich result."), faq("Where should I put the generated JSON-LD?", "Add the script to the page that describes the represented content, then validate it with the tools recommended by your search platform."), faq("Does this publish the structured data?", "No. The generator creates markup locally for you to add to your site.")],
  "web-seo/sitemap-generator": [faq("How do I generate a sitemap?", "Enter the page URLs you want included and generate the XML sitemap content."), faq("Does it discover pages automatically?", "No. You supply the URLs manually; the tool does not crawl your website."), faq("Where should I publish the sitemap?", "Save it as an XML file at a public URL on your site and reference it in your robots.txt or search console."), faq("Does a sitemap guarantee indexing?", "No. It helps expose URLs to crawlers, but indexing depends on the crawler and the page's eligibility.")],
  "web-seo/robots-generator": [faq("What does the robots.txt generator create?", "It builds crawler directives and optional sitemap declarations from the rules you select."), faq("Does robots.txt protect private pages?", "No. It is a public crawler convention, not security. Use authentication or server access controls for private content."), faq("Where should robots.txt go?", "Publish it at the root of the relevant host, such as https://example.com/robots.txt."), faq("Can a robots rule remove a page from search?", "Blocking crawling does not reliably remove a URL from search results. Use the appropriate indexing controls for your goal.")],
  "web-seo/canonical-checker": [faq("What input does the canonical checker need?", "Paste the page's HTML source so the tool can inspect its canonical link element."), faq("Does it fetch or crawl the page?", "No. It checks the HTML you paste; it cannot confirm the current live response unless you provide current source."), faq("What does a canonical tag tell search engines?", "It suggests a preferred URL for similar or duplicate pages. Search engines may choose a different canonical."), faq("Why might multiple canonical tags be a problem?", "Conflicting declarations can make the preferred URL unclear. Review the page template and rendered source for duplicates.")],
  "web-seo/seo-preview": [faq("What does the SEO snippet preview show?", "It displays an illustrative search result from the title, description, and URL you enter."), faq("Will search results use this exact text?", "No. Search engines may rewrite titles and descriptions or show different snippets for a query."), faq("Are the character limits strict?", "The preview is guidance. Search snippets can truncate or change based on pixel width and search context."), faq("Does the tool inspect my site?", "No. Enter the content to preview; the tool does not change or automatically fetch your page.")],
  "web-seo/slug-generator": [faq("What is a URL slug?", "A slug is the readable part of a URL that identifies a page, often derived from its title."), faq("How does the generator normalize text?", "It converts the text into a URL-friendly form using the tool's normalization rules, such as removing or replacing unsupported characters."), faq("Will changing a slug affect an existing page?", "Changing a live URL can break links. Set a redirect and update internal links if you change a published slug."), faq("Does it create the webpage URL?", "It generates the slug text only. Combine it with your site's route structure yourself.")],
  "web-seo/http-headers": [faq("How do I view response headers?", "Enter a URL and request its browser-accessible response headers. The browser may be limited by cross-origin policy."), faq("Why can only some headers be read?", "A server must expose headers through CORS for browser code to inspect them. Restricted headers may be unavailable."), faq("Are the headers the same for everyone?", "They can vary with location, request method, cookies, cache, and server configuration."), faq("Does the viewer send my URL to a third party?", "The browser requests the URL you enter. Use only public URLs you are comfortable checking.")],
  "web-seo/metadata-inspector": [faq("What input can I inspect?", "Paste HTML source to inspect its metadata. The tool parses the supplied text without executing it."), faq("Does it fetch a website for me?", "No. Copy the page source and paste it into the inspector if you want to review its metadata."), faq("Which metadata can it find?", "It reads supported document title, description, canonical, Open Graph, and related metadata from the provided markup."), faq("Can the inspector verify what crawlers receive?", "It only analyzes the HTML you provide. Server-rendered output, scripts, and crawler-specific behavior may differ.")],
  "web-seo/social-metadata-checker": [faq("What does this checker inspect?", "It reviews favicon declarations and supported Open Graph and X metadata from the HTML you provide."), faq("Why are social images not appearing?", "Confirm the image URL is public, valid, and compatible with platform requirements; caches can also delay updates."), faq("Does it test the live page automatically?", "No. Paste current HTML source to inspect it; the checker does not crawl the site."), faq("Does a passing check guarantee a social preview?", "No. Social platforms control their own parsing, caches, and display rules.")],
  "security/jwt-decoder": [faq("What can I see by decoding a JWT?", "The tool decodes the token's header and payload when they use the expected JWT format."), faq("Does decoding verify the signature?", "No. Decoding only reveals encoded content; it does not verify the signature or prove the token is authentic."), faq("Should I paste a private token here?", "Avoid sharing sensitive bearer tokens. Decoding is local in this app, but a token still grants access until it expires or is revoked."), faq("Why does my token fail to decode?", "Check that it has the expected dot-separated JWT segments and valid Base64URL encoding.")],
  "security/hash": [faq("What can I hash?", "Use the hash tool with supported text or file input and select an available digest algorithm."), faq("Can a hash be reversed to recover the input?", "Cryptographic hashes are designed to be one-way. A hash is not encryption and does not provide a way to decrypt the original."), faq("Is a file uploaded to calculate its hash?", "No. Hashing is performed locally in your browser."), faq("Will the hash prove a file is safe?", "No. A hash can help compare file identity, but it does not establish that a file is trustworthy.")],
  "security/hmac": [faq("What is an HMAC?", "An HMAC combines a secret key and message with a hash function to produce an authentication code."), faq("How do I verify an HMAC?", "Generate a code using the same key, message, and algorithm as the sender, then compare it using a secure verification process."), faq("Is the secret key uploaded?", "No. HMAC calculation runs locally in your browser. Still avoid using a shared device for sensitive secrets."), faq("Is HMAC encryption?", "No. HMAC authenticates data; it does not hide or encrypt the message.")],
  "security/base64": [faq("What is Base64 encoding?", "Base64 represents bytes using printable text characters. It is an encoding scheme, not encryption."), faq("How do I encode or decode text?", "Choose encode or decode mode, enter the text, and copy the resulting representation."), faq("Why does decoded text look corrupted?", "The input may not be valid Base64 or may represent binary data rather than text in the expected character encoding."), faq("Is the value sent to a server?", "No. Encoding and decoding happen locally in your browser.")],
  "security/uuid": [faq("What kind of UUID does the generator create?", "It generates random UUID identifiers using the browser's available randomness support."), faq("Can a UUID ever repeat?", "A collision is extremely unlikely for properly generated random UUIDs, but uniqueness is not an absolute guarantee."), faq("Are these UUIDs secure passwords?", "No. UUIDs identify records; use a dedicated password generator for credentials."), faq("Are generated IDs stored?", "No. They are generated locally and are not uploaded or saved by the tool.")],
  "data/csv-viewer": [faq("How do I inspect a CSV file?", "Choose a CSV file to preview its rows, filter data, and use the available cleanup options."), faq("Why do columns look misaligned?", "Delimiter, quoting, or malformed rows can affect parsing. Check that fields containing commas or quotes are escaped correctly."), faq("Does the cleaner overwrite my file?", "No. Download or copy the cleaned result as a separate output; the original file stays unchanged."), faq("Is my CSV uploaded?", "No. The file is processed locally in your browser, subject to the tool's documented size limits.")],
  "data/file-info": [faq("What file information can I inspect?", "The tool reports general file properties and supported image or PDF details such as dimensions, page count, or metadata."), faq("Why are some properties unavailable?", "The format may not contain the property, or the browser parser may not support it. Missing metadata does not establish a file's history."), faq("Does the tool change my file?", "No. It reads the selected file and displays properties without modifying it."), faq("Is my file uploaded for inspection?", "No. File inspection runs locally in your browser.")],
  "data/xml-inspector": [faq("What can the XML inspector do?", "It can format and validate XML or convert supported XML input to JSON."), faq("Why is my XML invalid?", "Check that tags are properly nested and closed, attributes are quoted, and there is a single document root."), faq("How is XML represented in JSON?", "XML and JSON have different data models. The tool follows its displayed mapping rules, so review attributes, repeated elements, and text nodes in the output."), faq("Does it load external entities or run scripts?", "No. XML is parsed locally; the tool does not resolve external entities, fetch URLs, execute scripts, or render XML as HTML.")],
  "color/convert": [faq("Which color formats can I convert?", "Enter a supported HEX, RGB, or HSL value to see equivalent formats and a color preview."), faq("Why is my color value rejected?", "Check the format and value ranges, such as valid HEX digits or RGB channels between 0 and 255."), faq("Can the preview guarantee the printed color?", "No. Screen rendering depends on display calibration, color profiles, and lighting; use a calibrated workflow for print."), faq("Is my color value stored?", "No. Conversion and preview run locally in your browser.")],
  "everyday/calculator": [faq("What expressions can I enter?", "The calculator supports arithmetic expressions with decimals, parentheses, percentages, and keyboard input."), faq("How are percentages interpreted?", "Percentage behavior follows the calculator's expression rules. Use parentheses to make the intended order explicit."), faq("Why is my expression rejected?", "Check for missing operators, unmatched parentheses, or unsupported functions. The calculator evaluates only supported arithmetic."), faq("Are calculations sent to a server?", "No. Calculation happens locally in your browser.")],
  "everyday/percentage-calculator": [faq("How do I find a percentage of a number?", "Enter the base value and percentage in the matching calculation to find the portion."), faq("How do I calculate percentage change?", "Enter the starting and ending values. The result compares the change with the original value."), faq("Can I add or subtract a percentage?", "Use the increase or decrease calculation and enter the starting amount and rate."), faq("Why can percentage change be undefined?", "Percentage change uses the original value as its reference, so a starting value of zero has no defined percentage change.")],
  "everyday/age-calculator": [faq("How do I calculate age?", "Enter the date of birth and the comparison date to see the calendar age in years, months, and days."), faq("Does it use today's date automatically?", "The comparison date is provided by the tool; you can change it to calculate age on another date."), faq("Why can age in days differ from years times 365?", "Calendar years include leap days and have different lengths. The result follows calendar dates."), faq("Does it calculate age by timezone?", "It compares selected calendar dates, not exact birth times or timezones.")],
  "everyday/tip-calculator": [faq("How do I split a bill with a tip?", "Enter the bill amount, tip rate, and number of people to calculate the tip, total, and per-person share."), faq("Is the tip calculated before or after tax?", "Enter the amount you want the tip based on. The tool does not determine a restaurant's tax or tipping policy."), faq("How is rounding handled?", "Displayed currency values may be rounded to cents, so individual shares can differ slightly when summed."), faq("Does it include service charges?", "No. Add any service charge or other amount to the bill input if you want it included.")],
  "everyday/gst-calculator": [faq("How do I add GST to a price?", "Enter the pre-tax amount and GST rate to calculate the tax and total."), faq("How do I extract GST from a tax-inclusive price?", "Use the inclusive calculation with the total price and applicable GST rate to estimate the tax portion and base amount."), faq("Which GST rate should I use?", "Enter the rate that applies to your transaction and jurisdiction; the tool does not determine tax obligations."), faq("Is this tax advice?", "No. It is a calculation aid. Confirm the correct rate and treatment with official guidance or a tax professional.")],
  "everyday/loan-calculator": [faq("How do I estimate a monthly loan payment?", "Enter the principal, annual interest rate, and repayment term to calculate an estimated regular payment."), faq("Does the estimate include fees or variable rates?", "No. The estimate uses the rate and terms you enter and may exclude fees, insurance, taxes, and rate changes."), faq("What does the amortization schedule show?", "It estimates how each payment is divided between principal and interest over the entered term."), faq("Can I use this as a lender quote?", "No. It is an estimate for planning; the lender's actual offer and repayment schedule may differ.")],
  "everyday/date-time": [faq("What date calculations are available?", "Use the tool to add or subtract calendar time and inspect details such as weekday, leap year, or day of year."), faq("What happens when adding months to a date near month end?", "Months have different lengths, so the result follows the tool's calendar date behavior. Review the resulting date for month-end cases."), faq("Does it handle leap years?", "Yes. Calendar detail calculations account for leap years in the selected date."), faq("Are times converted between timezones?", "This tool focuses on date arithmetic and details. Use the timezone converter for cross-timezone clock conversion.")],
  "everyday/random-generator": [faq("What can the random generator do?", "Generate an integer in a chosen range, pick an item from a list, or shuffle the list locally."), faq("Is the integer range inclusive?", "The tool's selected minimum and maximum define the range; check the displayed values before generating."), faq("Is the result suitable for cryptographic secrets?", "Use dedicated cryptographic key-generation practices for secrets. A general random picker is not a security guarantee."), faq("Is my list uploaded?", "No. Generation and list selection run locally in your browser.")],
  "student/image-to-text": [faq("What kind of images work best for OCR?", "Use a sharp, well-lit image with printed English text, straight pages, and strong contrast for the best results."), faq("Does OCR support handwriting or other languages?", "This tool is intended for printed English. Handwriting and other languages are not supported reliably."), faq("Why are some words recognized incorrectly?", "OCR is approximate and can be affected by blur, layout, unusual fonts, or low contrast. Review the extracted text."), faq("Is my image uploaded?", "The image stays in your browser. The OCR worker and English language model are loaded from jsDelivr when needed.")],
  "student/notes-to-markdown": [faq("How do I format plain notes?", "Paste your notes and choose the optional structure you want, such as headings, lists, or checklists, then review the Markdown."), faq("Does it understand the meaning of my notes?", "No. It applies formatting rules to the text; it does not verify facts or infer missing information."), faq("Can I edit the generated Markdown?", "Yes. Review and edit the output before copying it into your notes or Markdown editor."), faq("Are my study notes uploaded?", "No. Formatting runs locally in your browser and input is not saved.")],
  "student/citation-helper": [faq("Which citation styles are available?", "The helper creates editable citation drafts in APA 7, MLA 9, or Chicago author-date from the source details you provide."), faq("Does it support every source type?", "It provides source-specific fields for common sources. If your source does not fit, verify the format against the current style guide."), faq("Are the citations guaranteed correct?", "No. Drafts can need corrections for missing fields, editions, capitalization, and institution-specific rules. Review before submitting."), faq("Is my research information saved?", "No. Citation formatting runs locally in your browser; the entered details are not uploaded or saved.")],
  "student/apa-reference": [faq("What does the APA 7 builder create?", "It creates a source-specific APA 7 reference and in-text citation draft from the publication details you enter."), faq("What if I do not know a source detail?", "Leave unavailable fields blank when allowed and consult the source itself. Do not guess publication data."), faq("Can I submit the generated citation as-is?", "Review it against APA 7 guidance and your instructor's requirements, especially for unusual sources."), faq("Are my source details uploaded?", "No. The reference draft is generated locally in your browser.")],
  "student/text-utilities": [faq("What text operations are available?", "Use the tools for case conversion, sorting lines, removing duplicate or empty lines, and literal find-and-replace."), faq("Does find-and-replace use regular expressions?", "No. It treats the search text literally. Use the Regex Tester for pattern-based replacements or matching."), faq("Can I apply an operation to multiple lines?", "Yes. Paste multiline text and select the operation. Review the output because line order or spacing may change."), faq("Is my text stored?", "No. Text utilities run locally in your browser and do not upload or save the input.")],
  "student/study-timer": [faq("How do I start a focus session?", "Choose a Pomodoro, break, or custom-duration preset, then start the countdown."), faq("Does the timer keep running if I close the page?", "The timer runs in the current browser page. Keep the page open to follow the countdown reliably."), faq("Will it play an alarm or send a notification?", "The tool's visible timer is the primary signal. Browser notification and sound behavior depends on the controls and browser permissions shown."), faq("Is my study activity tracked?", "No. The timer runs locally and does not upload or save your session history.")],
  "student/flashcard-generator": [faq("How do I generate flashcards from notes?", "Paste notes using clear term-and-definition or question-and-answer patterns, then generate cards for review."), faq("Can I edit generated cards?", "Yes. Review and edit the cards because simple local rules may split or interpret notes imperfectly."), faq("Does it automatically quiz me?", "It generates editable revision cards; use the available review controls to study them."), faq("Are my notes uploaded?", "No. Flashcard generation runs locally in your browser and does not save the input.")],
  "student/notes-organizer": [faq("Where are my notes stored?", "Notes are saved in this browser's local storage on this device. They are not synced to an account or uploaded."), faq("Will my notes appear on another device?", "No. Local storage is specific to this browser and device. Export notes if you need to move or back them up."), faq("How can I find and organize notes?", "Create notes, add tags, and use search to find matching saved content."), faq("How do I remove or back up my notes?", "Use the organizer's export and delete controls. Clearing browser storage can also remove notes, so export anything you need first.")],
};

export function getToolFaqs(tool: ToolDefinition): FaqSet {
  const key = `${tool.category}/${tool.slug}`;
  const result = faqSets[key];
  if (!result) throw new Error(`FAQ content is missing for ${tool.href}`);
  return result;
}

